package org.beckenburg;
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.List;
import java.util.function.*;

/** Visible sound bounds and falloff authoring, paired with the actual game preview. */
final class SoundVolumeEditor extends JPanel implements AutoCloseable {
    record View(SoundDocument document,String selected,boolean visible){}
    private final Map<String,SoundDocument> documents=new LinkedHashMap<>(),saved=new LinkedHashMap<>();
    private final Map<String,Deque<SoundDocument>> undo=new HashMap<>();
    private final DefaultListModel<String> rows=new DefaultListModel<>();private final JList<String> list=new JList<>(rows);
    private final JComboBox<SoundVolume.Kind> kind=new JComboBox<>(SoundVolume.Kind.values());private final JComboBox<SoundVolume.Shape> shape=new JComboBox<>(SoundVolume.Shape.values());private final JComboBox<SoundVolume.Source> source=new JComboBox<>(SoundVolume.Source.values());
    private final Map<String,JSpinner> numbers=new LinkedHashMap<>();private final JCheckBox enabled=new JCheckBox("Enabled",true),loop=new JCheckBox("Loop",true),power=new JCheckBox("Requires breaker power"),visible=new JCheckBox("Show 3D bounds + falloff",true),audition=new JCheckBox("Audition at preview camera");
    private final JLabel status=new JLabel("Select a sound volume");private final Consumer<View> changed;private final Consumer<SoundVolume> focus;private final Supplier<double[]> origin;private String level="castle";private boolean updating;private double cx,cz,zoom=12;private int dragX,dragZ;private SoundVolume dragOriginal;
    private final SoundVolumeAudio audio=new SoundVolumeAudio(new SoundDocument("preview",List.of()));
    private final JPanel plan=new JPanel(){protected void paintComponent(Graphics graphics){super.paintComponent(graphics);paintPlan((Graphics2D)graphics);}};
    SoundVolumeEditor(Supplier<double[]> origin,Consumer<View> changed,Consumer<SoundVolume> focus){super(new BorderLayout(3,3));this.origin=origin;this.changed=changed;this.focus=focus;
        var top=new JPanel(new BorderLayout());var buttons=new JPanel(new GridLayout(2,3,3,3));button(buttons,"Add sound",this::add);button(buttons,"Copy",this::copy);button(buttons,"Remove",this::remove);button(buttons,"Undo",this::undo);button(buttons,"Save",this::save);button(buttons,"Focus",()->{var v=selected();if(v!=null)focus.accept(v);});top.add(buttons,BorderLayout.NORTH);plan.setPreferredSize(new Dimension(400,170));plan.setBackground(new Color(20,28,32));top.add(plan,BorderLayout.CENTER);var toggles=new JPanel(new GridLayout(2,1));toggles.add(visible);toggles.add(audition);top.add(toggles,BorderLayout.SOUTH);add(top,BorderLayout.NORTH);
        var body=new JPanel(new BorderLayout(3,3));list.setVisibleRowCount(3);body.add(new JScrollPane(list),BorderLayout.NORTH);var fields=new JPanel(new GridLayout(0,2,3,4));field(fields,"Category",kind);field(fields,"Volume shape",shape);field(fields,"Sound source",source);
        number(fields,"X",0,-10000,10000,.25);number(fields,"Y (centre)",2,-10000,10000,.25);number(fields,"Z",0,-10000,10000,.25);number(fields,"Width / diameter",8,.1,2000,.25);number(fields,"Height",4,.1,2000,.25);number(fields,"Depth",8,.1,2000,.25);number(fields,"Falloff (m)",4,.01,1000,.25);number(fields,"Gain",.18,0,1,.01);number(fields,"Pitch",1,.25,4,.05);number(fields,"Fade (seconds)",.5,.02,10,.05);number(fields,"One-shot duration (s)",8,.1,60,.5);fields.add(enabled);fields.add(loop);fields.add(power);fields.add(new JLabel(""));body.add(new JScrollPane(fields),BorderLayout.CENTER);add(body,BorderLayout.CENTER);add(status,BorderLayout.SOUTH);
        list.addListSelectionListener(e->{if(!updating&&!e.getValueIsAdjusting()){refreshFields();publish();}});for(var c:new JComboBox<?>[]{kind,shape,source})c.addActionListener(e->apply());for(var c:List.of(enabled,loop,power))c.addActionListener(e->apply());visible.addActionListener(e->publish());audition.addActionListener(e->audio.active(audition.isSelected()));
        plan.addMouseListener(new MouseAdapter(){public void mousePressed(MouseEvent e){dragX=e.getX();dragZ=e.getY();double x=cx+(e.getX()-plan.getWidth()/2d)/zoom,z=cz+(e.getY()-plan.getHeight()/2d)/zoom;SoundVolume hit=null;for(var v:document().volumes())if(Math.abs(v.x()-x)<=v.width()/2&&Math.abs(v.z()-z)<=v.depth()/2)hit=v;if(hit!=null){list.setSelectedValue(hit.id(),true);dragOriginal=hit;history();}}public void mouseReleased(MouseEvent e){dragOriginal=null;}});
        plan.addMouseMotionListener(new MouseMotionAdapter(){public void mouseDragged(MouseEvent e){if(dragOriginal==null)return;replace(dragOriginal.move(dragOriginal.x()+(e.getX()-dragX)/zoom,dragOriginal.y(),dragOriginal.z()+(e.getY()-dragZ)/zoom),false);}});plan.addMouseWheelListener(e->{zoom=Math.max(.3,Math.min(100,zoom*Math.pow(1.15,-e.getPreciseWheelRotation())));plan.repaint();});
    }
    private static void button(JPanel p,String text,Runnable action){var b=new JButton(text);b.addActionListener(e->action.run());p.add(b);}
    private static void field(JPanel p,String label,JComponent c){p.add(new JLabel(label));p.add(c);}
    private void number(JPanel p,String name,double value,double min,double max,double step){var s=new JSpinner(new SpinnerNumberModel(value,min,max,step));numbers.put(name,s);field(p,name,s);s.addChangeListener(e->apply());}
    private double n(String key){return ((Number)numbers.get(key).getValue()).doubleValue();}
    private SoundDocument document(){return documents.getOrDefault(level,new SoundDocument(level,List.of()));}
    private SoundVolume selected(){String id=list.getSelectedValue();return document().volumes().stream().filter(v->v.id().equals(id)).findFirst().orElse(null);}
    void map(String id){level=id;var doc=documents.computeIfAbsent(id,SoundDocument::load);saved.putIfAbsent(id,doc);refresh(null);if(!doc.volumes().isEmpty()){var v=doc.volumes().get(0);cx=v.x();cz=v.z();list.setSelectedValue(v.id(),true);}else{var p=origin.get();cx=p[0];cz=p[2];}publish();}
    private void history(){var h=undo.computeIfAbsent(level,k->new ArrayDeque<>());h.push(document());while(h.size()>60)h.removeLast();}
    private void refresh(String id){updating=true;rows.clear();for(var v:document().volumes())rows.addElement(v.id());if(id!=null)list.setSelectedValue(id,true);updating=false;refreshFields();publish();}
    private void refreshFields(){var v=selected();updating=true;for(var c:List.of(kind,shape,source,enabled,loop,power))c.setEnabled(v!=null);for(var s:numbers.values())s.setEnabled(v!=null);if(v!=null){kind.setSelectedItem(v.kind());shape.setSelectedItem(v.shape());source.setSelectedItem(v.source());double[] values={v.x(),v.y(),v.z(),v.width(),v.height(),v.depth(),v.falloff(),v.gain(),v.pitch(),v.fade(),v.duration()};int i=0;for(var s:numbers.values())s.setValue(values[i++]);enabled.setSelected(v.enabled());loop.setSelected(v.loop());power.setSelected(v.requiresPower());}updating=false;}
    private void replace(SoundVolume v,boolean remember){if(remember)history();var all=new ArrayList<>(document().volumes());for(int i=0;i<all.size();i++)if(all.get(i).id().equals(v.id()))all.set(i,v);documents.put(level,new SoundDocument(level,all));refresh(v.id());}
    private void apply(){if(updating||selected()==null)return;try{var old=selected();replace(new SoundVolume(old.id(),(SoundVolume.Kind)kind.getSelectedItem(),(SoundVolume.Shape)shape.getSelectedItem(),(SoundVolume.Source)source.getSelectedItem(),n("X"),n("Y (centre)"),n("Z"),n("Width / diameter"),n("Height"),n("Depth"),n("Falloff (m)"),n("Gain"),n("Pitch"),n("Fade (seconds)"),n("One-shot duration (s)"),enabled.isSelected(),loop.isSelected(),power.isSelected()),true);}catch(IllegalArgumentException e){status.setText(e.getMessage());refreshFields();}}
    private String nextId(){int i=1;while(rows.contains("sound-"+i))i++;return "sound-"+i;}
    private void add(){try{var p=origin.get();insert(SoundVolume.create(nextId(),p[0],p[1],p[2]));}catch(IllegalArgumentException e){status.setText(e.getMessage());}}
    private void insert(SoundVolume v){var all=new ArrayList<>(document().volumes());all.add(v);var next=new SoundDocument(level,all);history();documents.put(level,next);cx=v.x();cz=v.z();refresh(v.id());}
    private void copy(){var v=selected();if(v==null)return;try{insert(new SoundVolume(nextId(),v.kind(),v.shape(),v.source(),v.x()+2,v.y(),v.z()+2,v.width(),v.height(),v.depth(),v.falloff(),v.gain(),v.pitch(),v.fade(),v.duration(),v.enabled(),v.loop(),v.requiresPower()));}catch(IllegalArgumentException e){status.setText(e.getMessage());}}
    private void remove(){var v=selected();if(v==null)return;history();documents.put(level,new SoundDocument(level,document().volumes().stream().filter(x->!x.id().equals(v.id())).toList()));refresh(null);}
    private void undo(){var h=undo.get(level);if(h!=null&&!h.isEmpty()){documents.put(level,h.pop());refresh(null);}}
    private void save(){try{document().save(SoundDocument.path(level));saved.put(level,document());status.setText("Saved sound layout · reload playable map to activate");}catch(java.io.IOException e){status.setText("Save failed: "+e.getMessage());}}
    boolean dirty(){return documents.entrySet().stream().anyMatch(e->!e.getValue().equals(saved.get(e.getKey())));}
    void saveAll()throws java.io.IOException{for(var d:documents.values())if(!d.equals(saved.get(d.level()))){d.save(SoundDocument.path(d.level()));saved.put(d.level(),d);}}
    private void publish(){var d=document();audio.document(d);changed.accept(new View(d,list.getSelectedValue(),visible.isSelected()));plan.repaint();status.setText(d.volumes().size()+" sound volumes · dashed = falloff · drag to move");}
    void listener(double x,double y,double z,double yaw){audio.listener(x,y,z,yaw,true);}
    private void paintPlan(Graphics2D g){g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(Color.GRAY);g.drawString("SOUND PLAN · X/Z · wheel zoom · Y in inspector",6,14);for(var v:document().volumes()){int x=(int)(plan.getWidth()/2+(v.x()-cx)*zoom),z=(int)(plan.getHeight()/2+(v.z()-cz)*zoom),w=(int)(v.width()*zoom),d=(int)(v.depth()*zoom),f=(int)(v.falloff()*zoom);g.setColor(v.id().equals(list.getSelectedValue())?Color.YELLOW:new Color(100,210,150));g.setStroke(new BasicStroke(1,BasicStroke.CAP_BUTT,BasicStroke.JOIN_MITER,10,new float[]{4,4},0));if(v.shape()==SoundVolume.Shape.SPHERE)g.drawOval(x-w/2-f,z-d/2-f,w+2*f,d+2*f);else g.drawRoundRect(x-w/2-f,z-d/2-f,w+2*f,d+2*f,2*f,2*f);g.setStroke(new BasicStroke(2));if(v.shape()==SoundVolume.Shape.SPHERE)g.drawOval(x-w/2,z-d/2,w,d);else g.drawRect(x-w/2,z-d/2,w,d);g.fillRect(x-3,z-3,6,6);g.drawString(v.id(),x+6,z-3);}}
    public void close(){audio.close();}
}
